solution.solution.c:
#include <stdint.h>

void put_u16_le(unsigned char *out, uint16_t v)
{
    out[0] = (unsigned char)(v & 0xFF);
    out[1] = (unsigned char)(v >> 8);
}

uint16_t get_u16_le(const unsigned char *in)
{
    return (uint16_t)(in[0] | (in[1] << 8));
}

void put_u32_be(unsigned char *out, uint32_t v)
{
    out[0] = (unsigned char)(v >> 24);
    out[1] = (unsigned char)(v >> 16);
    out[2] = (unsigned char)(v >> 8);
    out[3] = (unsigned char)v;
}

uint32_t get_u32_be(const unsigned char *in)
{
    return (uint32_t)in[0] << 24 | (uint32_t)in[1] << 16 | (uint32_t)in[2] << 8 | in[3];
}

uint32_t swap_bytes(uint32_t v)
{
    return (v >> 24) | ((v >> 8) & 0xFF00u) | ((v << 8) & 0xFF0000u) | (v << 24);
}

unitTests:
TEST("16 bits, little-endian") { unsigned char b[2]; put_u16_le(b, 0x1234); CHECK_EQ(b[0], 0x34); CHECK_EQ(b[1], 0x12); CHECK_EQ(get_u16_le(b), 0x1234); unsigned char m[2] = {0xFF, 0xFF}; CHECK_EQ(get_u16_le(m), 65535); }
TEST("32 bits, big-endian") { unsigned char b[4]; put_u32_be(b, 0xCAFEBABEu); CHECK_EQ(b[0], 0xCA); CHECK_EQ(b[1], 0xFE); CHECK_EQ(b[2], 0xBA); CHECK_EQ(b[3], 0xBE); CHECK_EQ(get_u32_be(b), 0xCAFEBABEu); }
TEST("high bytes do not go negative") { unsigned char b[4] = {0x80, 0x00, 0x00, 0x01}; CHECK_EQ(get_u32_be(b), 0x80000001u); unsigned char f[4] = {0xFF, 0xFF, 0xFF, 0xFF}; CHECK_EQ(get_u32_be(f), 0xFFFFFFFFu); }
TEST("swapping bytes") { CHECK_EQ(swap_bytes(0x11223344u), 0x44332211u); CHECK_EQ(swap_bytes(0xFF000000u), 0x000000FFu); CHECK_EQ(swap_bytes(swap_bytes(0xDEADBEEFu)), 0xDEADBEEFu); }

